css:
.pk-inv { font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif; color:#2b2b2b; font-size:12px; }
.pk-inv table { border-collapse: collapse; }
.pk-head { display:flex; justify-content:space-between; align-items:flex-start; padding-bottom:12px; border-bottom:3px solid #0b6e4f; }
.pk-company { font-size:18px; font-weight:700; color:#0b6e4f; }
.pk-meta { color:#5a6a6c; font-size:11px; margin-top:4px; line-height:1.5; }
.pk-title { text-align:right; }
.pk-title .en { font-size:18px; font-weight:700; color:#0b6e4f; letter-spacing:.5px; }
.pk-title .sub { font-size:10px; color:#7f9295; text-transform:uppercase; letter-spacing:.6px; margin-top:3px; }
.pk-strip { display:flex; background:#f0f6f3; border-radius:6px; margin:14px 0; padding:9px 14px; }
.pk-strip .cell { flex:1; }
.pk-strip .lbl { font-size:9.5px; color:#7f9295; text-transform:uppercase; letter-spacing:.4px; }
.pk-strip .val { font-size:13px; font-weight:600; margin-top:2px; }
.pk-parties { display:flex; gap:12px; margin:0 0 14px; }
.pk-party { flex:1; border:1px solid #e1e8e9; border-radius:6px; padding:10px 12px; }
.pk-party h4 { margin:0 0 6px; font-size:10.5px; color:#0b6e4f; text-transform:uppercase; letter-spacing:.4px; border-bottom:1px solid #eef2f3; padding-bottom:4px; }
.pk-party .nm { font-weight:700; font-size:13px; }
.pk-party div { line-height:1.5; }
.pk-items { width:100%; margin-top:2px; font-size:11px; }
.pk-items thead th { background:#0b6e4f; color:#fff; padding:8px 6px; text-align:center; font-weight:600; line-height:1.25; }
.pk-items tbody td { padding:7px 6px; border-bottom:1px solid #eceff0; vertical-align:top; }
.pk-items tbody tr:nth-child(even) { background:#f8fafa; }
.pk-items tfoot td { padding:8px 6px; font-weight:700; border-top:2px solid #0b6e4f; }
.pk-items .l { text-align:left; }
.pk-items .r { text-align:right; }
.pk-items .c { text-align:center; }
.pk-words { font-size:11px; color:#444; background:#f8fafa; border-radius:5px; padding:8px 12px; margin-top:12px; }
.pk-words-ur { margin-top:6px; font-size:13px; line-height:1.7; text-align:right; }
.pk-cert { margin-top:16px; font-size:11px; color:#444; line-height:1.6; }
.pk-signs { display:flex; gap:40px; margin-top:48px; }
.pk-sign { flex:1; text-align:center; font-size:10.5px; color:#5a6a6c; }
.pk-sign .line { border-top:1px solid #9aa7a9; margin:0 10px 5px; padding-top:5px; }
.pk-foot { margin-top:18px; border-top:1px solid #e1e8e9; padding-top:9px; font-size:10px; color:#8a9698; text-align:center; line-height:1.5; }
